#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { existsSync, lstatSync, realpathSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// These are the current required contexts generated by jobs.unit's 1–4 matrix,
// plus verify and pgtap in .github/workflows/ci.yml.
const REQUIRED_CHECKS = ["unit (1)", "unit (2)", "unit (3)", "unit (4)", "verify", "pgtap"];
const SHA_PATTERN = /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/i;
const SCRIPT_PATH = fileURLToPath(import.meta.url);

class CleanupFailure extends Error {
  constructor(stage, message) {
    super(message);
    this.name = "CleanupFailure";
    this.stage = stage;
  }
}

function fail(stage, message) {
  throw new CleanupFailure(stage, message);
}

function parseArguments(argv) {
  const values = new Map();
  for (let index = 0; index < argv.length; index += 1) {
    const flag = argv[index];
    if (!["--pr", "--worktree", "--expected-head", "--base"].includes(flag)) {
      fail("arguments", "unknown or incomplete argument");
    }
    if (values.has(flag) || index + 1 >= argv.length || argv[index + 1].startsWith("--")) {
      fail("arguments", "duplicate or missing argument value");
    }
    values.set(flag, argv[index + 1]);
    index += 1;
  }

  const pr = values.get("--pr");
  const worktree = values.get("--worktree");
  const expectedHead = values.get("--expected-head")?.toLowerCase();
  const base = values.get("--base");
  if (!/^[1-9][0-9]*$/.test(pr ?? "")) fail("arguments", "PR number must be a positive integer");
  if (!path.isAbsolute(worktree ?? "")) fail("arguments", "worktree path must be absolute");
  if (!SHA_PATTERN.test(expectedHead ?? "")) fail("arguments", "expected head must be a commit ID");
  if (base !== "dev") fail("arguments", "only the dev base is accepted");
  return { pr, worktree, expectedHead, base };
}

function spawnProcess(tool, args, { cwd, stage }) {
  const result = spawnSync(tool, args, {
    cwd,
    encoding: "utf8",
    env: process.env,
    maxBuffer: 2 * 1024 * 1024,
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.error || result.signal) fail(stage, tool + " process could not complete");
  return result;
}

function runProcess(tool, args, { cwd, stage, allowedStatuses = [0] }) {
  const result = spawnProcess(tool, args, { cwd, stage });
  if (!allowedStatuses.includes(result.status)) {
    const code = Number.isInteger(result.status) ? "exit " + result.status : "unknown status";
    fail(stage, tool + " command failed (" + code + ")");
  }
  return result.stdout ?? "";
}

function runStatus(tool, args, { cwd, stage, allowedStatuses }) {
  const result = spawnProcess(tool, args, { cwd, stage });
  if (!allowedStatuses.includes(result.status)) {
    const code = Number.isInteger(result.status) ? "exit " + result.status : "unknown status";
    fail(stage, tool + " command failed (" + code + ")");
  }
  return result.status;
}

function runGit(args, options) {
  return runProcess("git", args, options);
}

function runGh(args, options) {
  return runProcess("gh", args, options);
}

function parseJson(output, stage, label) {
  try {
    return JSON.parse(output);
  } catch {
    fail(stage, label + " response was malformed");
  }
}

function requireSha(value, stage, label) {
  if (typeof value !== "string" || !SHA_PATTERN.test(value)) {
    fail(stage, label + " was missing or malformed");
  }
  return value.toLowerCase();
}

function requireNonEmptyString(value, stage, label) {
  if (typeof value !== "string" || value.length === 0 || /[\u0000-\u001f\u007f]/.test(value)) {
    fail(stage, label + " was missing or malformed");
  }
  return value;
}

function parseWorktrees(output, stage) {
  const normalized = output.replace(/\r\n/g, "\n").trim();
  if (!normalized) fail(stage, "git returned no registered worktrees");
  const entries = [];
  const seen = new Set();
  for (const block of normalized.split(/\n\n+/)) {
    let worktreePath;
    let head;
    let branch;
    for (const line of block.split("\n")) {
      if (line.startsWith("worktree ")) {
        if (worktreePath !== undefined) fail(stage, "worktree listing contained duplicate path data");
        worktreePath = line.slice("worktree ".length);
      } else if (line.startsWith("HEAD ")) {
        if (head !== undefined) fail(stage, "worktree listing contained duplicate head data");
        head = line.slice("HEAD ".length);
      } else if (line.startsWith("branch ")) {
        if (branch !== undefined) fail(stage, "worktree listing contained duplicate branch data");
        branch = line.slice("branch ".length);
      } else if (line.startsWith("detached")) {
        branch = null;
      } else if (line && !/^(bare|locked|prunable)(?: |$)/.test(line)) {
        fail(stage, "worktree listing contained malformed data");
      }
    }
    if (!worktreePath || !head) fail(stage, "worktree listing omitted path or head");
    requireSha(head, stage, "worktree head");
    const resolvedPath = path.resolve(worktreePath);
    if (seen.has(resolvedPath)) fail(stage, "worktree listing contained a duplicate path");
    seen.add(resolvedPath);
    entries.push({ path: resolvedPath, head: head.toLowerCase(), branch });
  }
  return entries;
}

function parseRemoteRef(output, branch, stage) {
  const normalized = output.trim();
  if (!normalized) return null;
  const lines = normalized.split(/\r?\n/);
  if (lines.length !== 1) fail(stage, "remote branch response was duplicated or malformed");
  const fields = lines[0].split(/\s+/);
  if (fields.length !== 2 || fields[1] !== "refs/heads/" + branch) {
    fail(stage, "remote branch response was malformed");
  }
  return requireSha(fields[0], stage, "remote branch head");
}

function resolveExistingDirectory(candidate, stage, label) {
  try {
    const resolved = realpathSync(candidate);
    if (!existsSync(resolved)) fail(stage, label + " does not exist");
    return resolved;
  } catch (error) {
    if (error instanceof CleanupFailure) throw error;
    fail(stage, label + " does not exist");
  }
}

function assertPathAbsent(candidate, stage, label) {
  try {
    lstatSync(candidate);
    fail(stage, label + " still existed");
  } catch (error) {
    if (error instanceof CleanupFailure) throw error;
    if (error?.code === "ENOENT") return;
    fail(stage, label + " could not be checked");
  }
}

function parseCiChecks(output, stage) {
  const checks = parseJson(output, stage, "CI checks");
  if (!Array.isArray(checks)) fail(stage, "CI checks response was not a list");
  const byName = new Map();
  for (const check of checks) {
    if (!check || typeof check !== "object") fail(stage, "CI checks response contained malformed data");
    const name = requireNonEmptyString(check.name, stage, "CI check name");
    if (byName.has(name)) fail(stage, "CI checks included a duplicate name");
    byName.set(name, check);
  }
  if (REQUIRED_CHECKS.some((name) => !byName.has(name))) {
    fail(stage, "CI checks did not include all six current gates");
  }
  for (const name of REQUIRED_CHECKS) {
    const check = byName.get(name);
    if (check.bucket !== "pass" || check.state !== "SUCCESS") {
      fail(stage, "CI gate " + name + " was not successful and complete");
    }
  }
  for (const [name, check] of byName) {
    if (REQUIRED_CHECKS.includes(name)) continue;
    const successful = check.bucket === "pass" && check.state === "SUCCESS";
    const skipped = check.bucket === "skipping" && check.state === "SKIPPED";
    const neutral = (check.bucket === "neutral" || check.bucket === "skipping") && check.state === "NEUTRAL";
    if (!successful && !skipped && !neutral) {
      fail(stage, "additional CI check " + name + " was not successful or skipped");
    }
  }
}

function changedPaths(output, stage) {
  if (output === "") return [];
  if (!output.endsWith("\0")) fail(stage, "changed-path response was malformed");
  const paths = output.slice(0, -1).split("\0");
  if (paths.some((filePath) => filePath.length === 0) || new Set(paths).size !== paths.length) {
    fail(stage, "changed-path response contained invalid or duplicate paths");
  }
  return paths;
}

function assertAttributionClear(repoRoot, baseCommit, head, stage) {
  const commitBodies = runGit(
    ["log", "--format=%B", baseCommit + ".." + head],
    { cwd: repoRoot, stage },
  );
  if (/co-authored/i.test(commitBodies)) fail(stage, "commit attribution marker blocks cleanup");
}

function ensureWorktree(worktreePath, repoRoot, branch, branchRef, expectedHead, stage) {
  const entries = parseWorktrees(
    runGit(["worktree", "list", "--porcelain"], { cwd: repoRoot, stage }),
    stage,
  );
  const entry = entries.find((candidate) => candidate.path === worktreePath);
  if (!entry || entry.branch !== branchRef || entry.head !== expectedHead) {
    fail(stage, "requested path was not the worktree for the expected branch and head");
  }
  const top = runGit(["-C", worktreePath, "rev-parse", "--show-toplevel"], { cwd: repoRoot, stage }).trim();
  if (path.resolve(top) !== worktreePath) fail(stage, "requested path was not the worktree root");
  const head = requireSha(
    runGit(["-C", worktreePath, "rev-parse", "HEAD"], { cwd: repoRoot, stage }).trim(),
    stage,
    "worktree head",
  );
  if (head !== expectedHead) fail(stage, "worktree head changed");
  const currentBranch = runGit(["-C", worktreePath, "branch", "--show-current"], { cwd: repoRoot, stage }).trim();
  if (currentBranch !== branch) fail(stage, "worktree branch changed");
  if (runGit(["-C", worktreePath, "status", "--porcelain=v1", "--untracked-files=all"], { cwd: repoRoot, stage }).trim()) {
    fail(stage, "worktree was not clean");
  }
}

function run() {
  let stage = "arguments";
  const completed = [];
  const attemptedMutations = [];
  try {
    const { pr, worktree, expectedHead, base } = parseArguments(process.argv.slice(2));
    stage = "repository";
    const repoRootOutput = runGit(["rev-parse", "--show-toplevel"], { cwd: process.cwd(), stage });
    if (!path.isAbsolute(repoRootOutput.trim())) fail(stage, "repository root was not an absolute path");
    const repoRoot = resolveExistingDirectory(repoRootOutput.trim(), stage, "repository root");
    const worktreePath = path.resolve(worktree);
    const canonicalWorktree = resolveExistingDirectory(worktreePath, stage, "requested worktree");
    if (repoRoot === canonicalWorktree) fail(stage, "requested worktree is the repository root");

    stage = "pull request";
    const initialPr = parseJson(
      runGh(["pr", "view", pr, "--json", "state,baseRefName,headRefName,headRefOid"], { cwd: repoRoot, stage }),
      stage,
      "pull request",
    );
    if (!initialPr || typeof initialPr !== "object") fail(stage, "pull request response was malformed");
    const branch = requireNonEmptyString(initialPr.headRefName, stage, "pull request head branch");
    if (initialPr.state !== "OPEN" || initialPr.baseRefName !== base) {
      fail(stage, "pull request must be open and target dev");
    }
    if (branch === base || ["main", "master", "production"].includes(branch)) {
      fail(stage, "branch is not eligible for cleanup");
    }
    if (requireSha(initialPr.headRefOid, stage, "pull request head") !== expectedHead) {
      fail(stage, "pull request head did not match the expected immutable head");
    }

    stage = "CI checks";
    const checksResult = spawnProcess("gh", ["pr", "checks", pr, "--json", "name,bucket,state"], { cwd: repoRoot, stage });
    if (![0, 1, 8].includes(checksResult.status)) fail(stage, "gh checks command did not complete");
    parseCiChecks(checksResult.stdout ?? "", stage);
    if (checksResult.status !== 0) fail(stage, "gh checks command did not report a clean status");

    stage = "worktree preflight";
    runGit(["check-ref-format", "--branch", branch], { cwd: repoRoot, stage });
    const branchRef = "refs/heads/" + branch;
    ensureWorktree(worktreePath, repoRoot, branch, branchRef, expectedHead, stage);
    const localHead = requireSha(runGit(["rev-parse", branchRef], { cwd: repoRoot, stage }).trim(), stage, "local branch head");
    if (localHead !== expectedHead) fail(stage, "local branch did not match the expected immutable head");
    const remoteHead = parseRemoteRef(
      runGit(["ls-remote", "--heads", "origin", branchRef], { cwd: repoRoot, stage }),
      branch,
      stage,
    );
    if (remoteHead !== null && remoteHead !== expectedHead) {
      fail(stage, "remote branch did not match the expected immutable head");
    }

    stage = "pre-merge base fetch";
    runGit(
      ["fetch", "origin", "refs/heads/" + base + ":refs/remotes/origin/" + base],
      { cwd: repoRoot, stage },
    );

    stage = "pre-merge change set";
    const preMergeBase = requireSha(
      runGit(["merge-base", expectedHead, "refs/remotes/origin/" + base], { cwd: repoRoot, stage }).trim(),
      stage,
      "pre-merge base",
    );
    const filesChangedByHead = changedPaths(
      runGit(["diff", "--name-only", "--no-renames", "-z", preMergeBase, expectedHead], { cwd: repoRoot, stage }),
      stage,
    );

    stage = "pre-merge attribution gate";
    assertAttributionClear(repoRoot, preMergeBase, expectedHead, stage);

    stage = "squash merge";
    attemptedMutations.push(stage);
    runGh(["pr", "merge", pr, "--squash", "--match-head-commit", expectedHead], { cwd: repoRoot, stage });
    completed.push("squash merge");

    stage = "merged result";
    const mergedPr = parseJson(
      runGh(
        ["pr", "view", pr, "--json", "state,mergeCommit,headRefName,headRefOid,baseRefName"],
        { cwd: repoRoot, stage },
      ),
      stage,
      "merged pull request",
    );
    if (!mergedPr || typeof mergedPr !== "object" ||
        mergedPr.state !== "MERGED" || mergedPr.baseRefName !== base ||
        mergedPr.headRefName !== branch ||
        requireSha(mergedPr.headRefOid, stage, "merged pull request head") !== expectedHead) {
      fail(stage, "pull request did not merge the expected head into dev");
    }
    const mergeOid = requireSha(mergedPr.mergeCommit?.oid, stage, "merge commit");

    stage = "base fetch";
    runGit(
      ["fetch", "origin", "refs/heads/" + base + ":refs/remotes/origin/" + base],
      { cwd: repoRoot, stage },
    );

    stage = "merge reachability";
    runGit(["merge-base", "--is-ancestor", mergeOid, "refs/remotes/origin/" + base], { cwd: repoRoot, stage });

    stage = "content adoption proof";
    for (const filePath of filesChangedByHead) {
      const adoptionStatus = runStatus(
        "git",
        [
          "diff", "--quiet", "--no-ext-diff", "--no-textconv", "--no-renames",
          expectedHead, "refs/remotes/origin/" + base, "--", ":(literal)" + filePath,
        ],
        { cwd: repoRoot, stage, allowedStatuses: [0, 1] },
      );
      if (adoptionStatus !== 0) fail(stage, "feature file content was not adopted on fetched dev");
    }

    stage = "post-merge tip verification";
    ensureWorktree(worktreePath, repoRoot, branch, branchRef, expectedHead, stage);
    const refreshedLocalHead = requireSha(
      runGit(["rev-parse", branchRef], { cwd: repoRoot, stage }).trim(),
      stage,
      "local branch head",
    );
    if (refreshedLocalHead !== expectedHead) fail(stage, "local branch changed after merge");
    const refreshedRemoteHead = parseRemoteRef(
      runGit(["ls-remote", "--heads", "origin", branchRef], { cwd: repoRoot, stage }),
      branch,
      stage,
    );
    if (refreshedRemoteHead !== null && refreshedRemoteHead !== expectedHead) {
      fail(stage, "remote branch changed after merge");
    }

    stage = "worktree removal";
    attemptedMutations.push(stage);
    runGit(["worktree", "remove", worktreePath], { cwd: repoRoot, stage });
    completed.push("worktree removal");
    const afterRemove = parseWorktrees(
      runGit(["worktree", "list", "--porcelain"], { cwd: repoRoot, stage }),
      stage,
    );
    if (afterRemove.some((entry) => entry.path === worktreePath)) fail(stage, "owned worktree remained registered after removal");
    assertPathAbsent(worktreePath, stage, "owned worktree");

    stage = "worktree prune";
    attemptedMutations.push(stage);
    runGit(["worktree", "prune"], { cwd: repoRoot, stage });
    completed.push("worktree prune");
    const afterPrune = parseWorktrees(
      runGit(["worktree", "list", "--porcelain"], { cwd: repoRoot, stage }),
      stage,
    );
    if (afterPrune.some((entry) => entry.path === worktreePath)) fail(stage, "owned worktree remained registered after prune");
    assertPathAbsent(worktreePath, stage, "owned worktree");

    stage = "local branch deletion";
    const deleteLocalHead = requireSha(
      runGit(["rev-parse", branchRef], { cwd: repoRoot, stage }).trim(),
      stage,
      "local branch head",
    );
    if (deleteLocalHead !== expectedHead) fail(stage, "local branch changed before deletion");
    attemptedMutations.push(stage);
    runGit(["update-ref", "-d", branchRef, expectedHead], { cwd: repoRoot, stage });
    completed.push("local branch deletion");

    stage = "local branch deletion verification";
    const remainingLocalRef = runStatus(
      "git",
      ["show-ref", "--verify", "--quiet", branchRef],
      { cwd: repoRoot, stage, allowedStatuses: [0, 1] },
    );
    if (remainingLocalRef !== 1) fail(stage, "local branch ref still existed after deletion");

    stage = "remote branch recheck";
    const finalRemoteHead = parseRemoteRef(
      runGit(["ls-remote", "--heads", "origin", branchRef], { cwd: repoRoot, stage }),
      branch,
      stage,
    );
    if (finalRemoteHead !== null && finalRemoteHead !== expectedHead) {
      fail(stage, "remote branch changed before deletion");
    }

    if (finalRemoteHead !== null) {
      stage = "pre-deletion attribution gate";
      assertAttributionClear(repoRoot, preMergeBase, expectedHead, stage);

      stage = "remote branch recheck before deletion";
      const immediateRemoteHead = parseRemoteRef(
        runGit(["ls-remote", "--heads", "origin", branchRef], { cwd: repoRoot, stage }),
        branch,
        stage,
      );
      if (immediateRemoteHead !== expectedHead) {
        fail(stage, "remote branch changed immediately before deletion");
      }

      stage = "remote branch deletion";
      attemptedMutations.push(stage);
      runGit(
        ["push", "--force-with-lease=" + branchRef + ":" + expectedHead, "origin", ":" + branchRef],
        { cwd: repoRoot, stage },
      );
      completed.push("remote branch deletion");
    }

    stage = "final absence proof";
    const localRefStatus = runStatus(
      "git",
      ["show-ref", "--verify", "--quiet", branchRef],
      { cwd: repoRoot, stage, allowedStatuses: [0, 1] },
    );
    if (localRefStatus !== 1) fail(stage, "local branch ref still existed at completion");
    const finalRemote = parseRemoteRef(
      runGit(["ls-remote", "--heads", "origin", branchRef], { cwd: repoRoot, stage }),
      branch,
      stage,
    );
    if (finalRemote !== null) fail(stage, "remote branch ref still existed at completion");
    const finalWorktrees = parseWorktrees(
      runGit(["worktree", "list", "--porcelain"], { cwd: repoRoot, stage }),
      stage,
    );
    if (finalWorktrees.some((entry) => entry.path === worktreePath)) {
      fail(stage, "owned worktree remained registered at completion");
    }
    assertPathAbsent(worktreePath, stage, "owned worktree");

    process.stdout.write("VERIFIED CLEANUP COMPLETE for PR #" + pr + " after final absence proof.\n");
  } catch (error) {
    const failure = error instanceof CleanupFailure
      ? error
      : new CleanupFailure(stage, "unexpected error");
    process.stderr.write("FAILED [" + failure.stage + "]: " + failure.message + "\n");
    if (completed.length > 0 || attemptedMutations.length > 0) {
      const inFlight = attemptedMutations.includes(failure.stage)
        ? "; failed stage may have partially applied"
        : "";
      process.stderr.write(
        "Partial state: completed " + (completed.join(", ") || "no recorded mutation")
        + inFlight + "; later cleanup was not attempted.\n",
      );
    }
    process.exitCode = 1;
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === SCRIPT_PATH) run();
